#include <iostream>
#include <iomanip>
using namespace std;
int main() {
    cout << fixed << setprecision(2) << setfill('.');
    cout << left << setw(8) << "Rice" << right << setw(8) << 95.5 << '\n';
    cout << left << setw(8) << "Lentils" << right << setw(8) << 160.0 << '\n';
    cout << setfill(' ') << hex << showbase << 255 << ' ' << dec << 255 << '\n';
    cout << scientific << setprecision(3) << 0.000123456 << '\n';
}

#include <iostream>
#include <string>
using namespace std;
int main() {
    int roll; char grade; string name; char city[6];
    cin >> roll;              // line 1 of input: 42
    cin.get(grade);           // reads the '\n' left behind by >>
    cin >> grade;             // skips whitespace, reads A
    cin.ignore(100, '\n');    // discards the rest of line 2
    getline(cin, name);       // line 3: Sita Rai
    cin.getline(city, 6);     // line 4: Biratnagar, only 5 chars fit
    cout << roll << '|' << grade << '|' << name << '|' << city << '|' << cin.fail();
}

